in cmdValida, accanto ai controlli su fonte e sensore:

  const CAUSE_AMMESSE = ["ipotesi-sbagliata", "esecuzione-mancata", "misura-cieca"];
  const DATA_PONTE = "2026-08-01"; // le righe precedenti sono storia e restano esenti
  for (const e of registro) {
    if (e.stato !== "mancata") continue;
    if (!e.chiuso_il || e.chiuso_il < DATA_PONTE) continue;
    if (!CAUSE_AMMESSE.includes(e.causa)) {
      problemi.push(`${e.id}: chiusa senza causa ammessa (${CAUSE_AMMESSE.join(" | ")}). Una previsione mancata che non dice PERCHÉ non insegna niente.`);
    }
  }

